- **`goto cleanup` pattern** for functions that acquire multiple resources:
```c
int sam3_do_thing(struct sam3_ctx *ctx)
{
	struct resource *a = NULL;
	struct resource *b = NULL;
	int err;

	a = acquire_a();
	if (!a) {
		err = SAM3_ENOMEM;
		goto cleanup;
	}

	b = acquire_b();
	if (!b) {
		err = SAM3_ENOMEM;
		goto cleanup;
	}

	err = use_resources(a, b);

cleanup:
	release_b(b);
	release_a(a);
	return err;
}
```

