            name: 'Blog',
            isPartOf: { '@id': ids.website },
            breadcrumb: { '@id': ids.breadcrumb(url) },
            about: { '@id': blogId },
        },
        ids,
        'CollectionPage',
    ),
    buildBreadcrumbList(
        {
            url,
            items: [
                { name: 'Home', url: siteUrl },
                { name: 'Blog', url },
            ],
        },
        ids,
    ),
];
```

